package com.lisdatasolutions.microrag.rag.ingest

/**
 * Python's `str` semantics that `offline/eval/extract.py` relies on, so the app extracts exactly as
 * the F05 evaluation did (F06 research R8). The character sets come from [PyTables], generated by
 * Python itself; letter case uses Java's code point tables, which agree with Python's for Lu, Ll and
 * Other_Uppercase/Lowercase.
 */
internal object PyText {

    fun isSpace(codePoint: Int): Boolean = inRanges(PyTables.SPACE_RANGES, codePoint)

    /** `str.isdigit()` of one code point: decimals plus other digits such as superscripts. */
    fun isDigit(codePoint: Int): Boolean = inRanges(PyTables.DIGIT_RANGES, codePoint)

    /** `\d` of a Python regex: category Nd. */
    fun isDecimal(codePoint: Int): Boolean = inRanges(PyTables.DECIMAL_RANGES, codePoint)

    fun isLineBreak(char: Char): Boolean = PyTables.LINE_BREAKS.binarySearch(char.code) >= 0

    fun isUpper(codePoint: Int): Boolean = Character.isUpperCase(codePoint)

    fun isLower(codePoint: Int): Boolean = Character.isLowerCase(codePoint)

    fun isAlpha(codePoint: Int): Boolean = Character.isLetter(codePoint)

    /** `str.splitlines()`: CR LF is one break and a final break adds no empty line. */
    fun splitLines(text: String): List<String> {
        val lines = ArrayList<String>()
        var start = 0
        var i = 0
        while (i < text.length) {
            val char = text[i]
            if (isLineBreak(char)) {
                lines += text.substring(start, i)
                i += if (char == '\r' && i + 1 < text.length && text[i + 1] == '\n') 2 else 1
                start = i
            } else {
                i++
            }
        }
        if (start < text.length) lines += text.substring(start)
        return lines
    }

    // Every Python space is in the Basic Multilingual Plane, so stripping can work on chars.

    fun strip(text: String): String = rstrip(lstrip(text))

    fun lstrip(text: String): String {
        var start = 0
        while (start < text.length && isSpace(text[start].code)) start++
        return text.substring(start)
    }

    fun rstrip(text: String): String {
        var end = text.length
        while (end > 0 && isSpace(text[end - 1].code)) end--
        return text.substring(0, end)
    }

    /** `" ".join(text.split())`: runs of spaces become one, ends trimmed. */
    fun collapseSpaces(text: String): String {
        val out = StringBuilder(text.length)
        var pendingSpace = false
        for (char in text) {
            if (isSpace(char.code)) {
                pendingSpace = out.isNotEmpty()
            } else {
                if (pendingSpace) out.append(' ')
                pendingSpace = false
                out.append(char)
            }
        }
        return out.toString()
    }

    /** `str.isdigit()` of a whole string. */
    fun isDigitString(text: String): Boolean {
        if (text.isEmpty()) return false
        var i = 0
        while (i < text.length) {
            val codePoint = text.codePointAt(i)
            if (!isDigit(codePoint)) return false
            i += Character.charCount(codePoint)
        }
        return true
    }

    fun firstCodePoint(text: String): Int = text.codePointAt(0)

    private fun inRanges(ranges: IntArray, codePoint: Int): Boolean {
        var low = 0
        var high = ranges.size / 2 - 1
        while (low <= high) {
            val mid = (low + high) ushr 1
            when {
                codePoint < ranges[2 * mid] -> high = mid - 1
                codePoint > ranges[2 * mid + 1] -> low = mid + 1
                else -> return true
            }
        }
        return false
    }
}
